/**
 * A header create that survives an ambiguous failure (dvopt T-09 part, CB-14): Contracts, Land Lease cost header, OPEX period.
 *
 * THE PROBLEM. A POST that Dataverse committed but whose answer never arrived (network drop, gateway timeout) is reported to the user as
 * a failure. Their retry of the same save creates a SECOND row, and the server cannot tell the two apart because it issued the id.
 *
 * THE FIX (as Add Cost from Table does, D51 §3a: `idCache` in `data/addCostSheet.ts`). The id is generated by the CLIENT
 * (`newRowId`, a POST that names its primary key creates the row with that id) and is KEPT while the create has not been confirmed. The
 * "same save" is the same entity set and the same payload, so a retry of an identical save reuses the id, and a retried id is READ BACK
 * by id before it is created again: when the row is there the earlier attempt landed, and that row is the result (nothing is created).
 * A confirmed create forgets its id, so two deliberate, identical creates one after the other still make two rows.
 *
 * LIMITS. A user who EDITS the form between the failure and the retry sends a different payload, so a new id (the earlier row, if it
 * landed, stays; nothing was lost, and it was a duplicate before this change too). The registry lives in the tab (a reload forgets it).
 * `STABLE_CREATE_IDS = false` restores the server-issued id and the single POST.
 */
import type { IOperationResult } from "@microsoft/power-apps/data";
import { unwrap } from "@/platform/errors";
import { STABLE_CREATE_IDS } from "./leaseOpexFlags";
import { newRowId } from "./newRowId";
import { rowExists } from "./costUpdateGuard";

type Row = Record<string, unknown>;

/** Ids issued to a create that has not been confirmed, by `entitySet|payload`. Bounded: the oldest is dropped past `MAX_PENDING`. */
const pending = new Map<string, string>();
const MAX_PENDING = 50;

/** Same value, same text, whatever the key order (a payload is rebuilt on every Save click). */
function stableJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stableJson).join(",")}]`;
  if (value !== null && typeof value === "object") {
    const entries = Object.entries(value as Row)
      .filter(([, v]) => v !== undefined)
      .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
      .map(([k, v]) => `${JSON.stringify(k)}:${stableJson(v)}`);
    return `{${entries.join(",")}}`;
  }
  return JSON.stringify(value) ?? "null";
}

export interface StableCreate {
  operation: string;
  entitySet: string;
  /** The primary-key column of the row (`vsb_landleaseprojectcostid`). */
  idField: string;
  payload: Row;
  /** The one POST (a generated service `create`, or `client.createRecordAsync`). */
  create: (payload: Row) => Promise<IOperationResult<Row>>;
  /** Overrides, for tests. */
  enabled?: boolean;
  exists?: (id: string) => Promise<boolean>;
  newId?: () => string;
}

export interface StableCreateResult {
  /** The row as the create returned it; `null` when a retried id was found already there (nothing was sent). */
  row: Row | null;
  id: string;
  /** True when an earlier attempt of this same save had landed. */
  reused: boolean;
}

/** Forget every unconfirmed id (tests). */
export function resetStableCreateIds(): void {
  pending.clear();
}

export async function createWithStableId(input: StableCreate): Promise<StableCreateResult> {
  const { operation, entitySet, idField, payload, create } = input;
  if (!(input.enabled ?? STABLE_CREATE_IDS)) {
    const row = unwrap(await create(payload), operation);
    const id = row[idField];
    return { row, id: typeof id === "string" ? id : "", reused: false };
  }
  const key = `${entitySet}|${stableJson(payload)}`;
  const prior = pending.get(key);
  if (prior !== undefined) {
    const exists = input.exists ?? ((id: string) => rowExists(`${operation} (read back)`, entitySet, id));
    // A failed read-back throws: the retry then fails visibly and keeps its id, rather than guessing and duplicating.
    if (await exists(prior)) {
      pending.delete(key);
      return { row: null, id: prior, reused: true };
    }
  }
  const id = prior ?? (input.newId ?? newRowId)();
  if (prior === undefined) {
    pending.set(key, id);
    if (pending.size > MAX_PENDING) pending.delete(pending.keys().next().value as string);
  }
  const row = unwrap(await create({ ...payload, [idField]: id }), operation);
  pending.delete(key);
  const returned = row[idField];
  return { row, id: typeof returned === "string" && returned ? returned : id, reused: false };
}
